// HostAgentServiceHandler is an implementation of the harness.relay.v1.HostAgentService service.
type HostAgentServiceHandler interface {
	// Says what this daemon is. Creates the host on the first call of a token made by `harness-client daemon login`.
	RegisterAgentHost(context.Context, *connect.Request[v1.RegisterAgentHostRequest]) (*connect.Response[v1.RegisterAgentHostResponse], error)
	// Load, every 30 s or so. Also what hands over away work (decision 16).
	ReportAgentHost(context.Context, *connect.Request[v1.ReportAgentHostRequest]) (*connect.Response[v1.ReportAgentHostResponse], error)
	// Long poll: the next work of this device's user that fits the host's capacity. Empty after wait_seconds.
	ClaimHostWork(context.Context, *connect.Request[v1.ClaimHostWorkRequest]) (*connect.Response[v1.ClaimHostWorkResponse], error)
	// Progress of claimed work. Renews the claim's lease.
	UpdateHostWork(context.Context, *connect.Request[v1.UpdateHostWorkRequest]) (*connect.Response[v1.UpdateHostWorkResponse], error)
	// Short-lived git credentials for a repository, from the code host connection.
	IssueGitCredentials(context.Context, *connect.Request[v1.IssueGitCredentialsRequest]) (*connect.Response[v1.IssueGitCredentialsResponse], error)
	// Opens a draft or ready pull request with the same identity as the credentials.
	OpenHostPullRequest(context.Context, *connect.Request[v1.OpenHostPullRequestRequest]) (*connect.Response[v1.OpenHostPullRequestResponse], error)
	// Supervisor of a team host: long poll for the members that should have a worker running.
	ListWantedWorkers(context.Context, *connect.Request[v1.ListWantedWorkersRequest]) (*connect.Response[v1.ListWantedWorkersResponse], error)
	// Supervisor of a team host: a fresh device token for a member's worker; the previous one stops working.
	IssueWorkerToken(context.Context, *connect.Request[v1.IssueWorkerTokenRequest]) (*connect.Response[v1.IssueWorkerTokenResponse], error)
}

